#!/usr/bin/env node
/* global process, console */
// Merge several electron-builder `latest-mac.yml` files (one per arch, built on separate runners)
// into a single one listing every mac artifact. electron-updater reads the `files:` list and
// picks the entry matching the running arch, so the release must ship ONE latest-mac.yml that
// knows about both the arm64 and the x64 zips.
//
//   node scripts/merge-latest-mac.mjs <output.yml> <input1.yml> <input2.yml> [...]
//
// Dependency-free on purpose: the file format is flat and generated by electron-builder, so a
// line-based merge is safe (top-level keys: version, files, path, sha512, releaseDate).
import { readFileSync, writeFileSync } from 'node:fs';

const [output, ...inputs] = process.argv.slice(2);
if (!output || inputs.length === 0) {
  console.error('usage: merge-latest-mac.mjs <output.yml> <input.yml> [...]');
  process.exit(2);
}

const docs = inputs.map((f) => readFileSync(f, 'utf8'));
const versions = new Set(docs.map((d) => /^version:\s*(.+)$/m.exec(d)?.[1]?.trim()));
if (versions.size !== 1) {
  console.error(`refusing to merge different versions: ${[...versions].join(', ')}`);
  process.exit(1);
}

const filesBlocks = docs.map(filesBlock);
const [base] = docs;
const merged = base.replace(filesBlock(base), filesBlocks.join(''));
writeFileSync(output, merged);
console.info(`merged ${inputs.length} files into ${output} (${countEntries(merged)} entries)`);

// Returns the text from the line after `files:` up to the next top-level key (exclusive).
function filesBlock(doc) {
  const m = /^files:\n((?:[ \t-].*\n?)*)/m.exec(doc);
  if (!m) throw new Error('no files: block found');
  return m[1];
}

function countEntries(doc) {
  return (filesBlock(doc).match(/^ {2}- url:/gm) ?? []).length;
}
